// [MEDIUM_PRIORITY] RESOURCE_SECURITY: Cipher mode appropriate
// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] UX_POLISH: Empty state handled
// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.diimport android.content.Contextimport com.roshan.persona.di.AppInitializerimport com.roshan.persona.init.DatabaseInitializerimport com.roshan.persona.init.TimberInitializerimport com.roshan.persona.init.PreloadInitializerimport dagger.Bindsimport dagger.Moduleimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * Runs all [AppInitializer] implementations in priority order. * * Initializers are contributed via Hilt multibinding — features add their own * initializers without app module needing to know about them. * * For Module 1, no initializers are registered yet (empty set). Module 2+ will * add real initializers via `@Binds @IntoSet` in their Hilt modules. */@Singletonclass AppInitializers @Inject constructor(    private val initializers: Set<@JvmSuppressWildcards AppInitializer>,) {    fun initializeAll(context: Context) {        if (initializers.isEmpty()) {            Timber.tag("NOUS.Init").i("No initializers registered (Module 1 — expected)")            return        }        initializers            .sortedBy { it.priority.order }            .forEach { initializer ->                val name = initializer.javaClass.simpleName                val phase = initializer.priority.name                Timber.tag("NOUS.Init").d("[%s] Running %s", phase, name)                val startNanos = System.nanoTime()                runCatching {                    if (initializer.isBlocking) {                        initializer.initialize(context)                    } else {                        Thread {                            runCatching { initializer.initialize(context) }                                .onFailure { Timber.tag("NOUS.Init").e(it, "[%s] %s failed", phase, name) }                        }.also { it.isDaemon = true; it.name = "NOUS-Init-$name" }.start()                    }                }.onFailure { throwable ->                    Timber.tag("NOUS.Init").e(throwable, "[%s] %s failed synchronously", phase, name)                    if (initializer.priority == Priority.CRITICAL) {                        throw IllegalStateException("Critical initializer $name failed", throwable)                    }                }                val elapsedMs = (System.nanoTime() - startNanos) / 1_000_000                Timber.tag("NOUS.Init").v("[%s] %s done in %dms", phase, name, elapsedMs)            }    }}/** * NOUS — App Initializers Hilt Module. * * Binds all real [AppInitializer] implementations via `@Binds @IntoSet` * multibinding. [AppInitializers] auto-discovers them in priority order. * * Initializers registered: *   - [DatabaseInitializer]        — CRITICAL, blocking (opens SQLCipher DB) *   - [TimberInitializer]          — CRITICAL, blocking (plants log tree) *   - [PreloadInitializer]         — LAZY, non-blocking (model preload stub) * * Feature modules can add their own initializers by creating a similar * `@Module @InstallIn(SingletonComponent::class)` with `@Binds @IntoSet`. */@Module@InstallIn(SingletonComponent::class)abstract class AppInitializersModule {    @Binds    @IntoSet    abstract fun bindDatabaseInitializer(impl: DatabaseInitializer): AppInitializer    @Binds    @IntoSet    abstract fun bindTimberInitializer(impl: TimberInitializer): AppInitializer    @Binds    @IntoSet    abstract fun bindPreloadInitializer(impl: PreloadInitializer): AppInitializer}// `Priority` enum has been moved to :core:di// (com.roshan.persona.di.Priority) so feature modules can contribute// AppInitializers without depending on :app.